gin-bottom: 12px;\n  word-break: break-all;\n  background-color: rgba(255,228,240,0.5);\n  padding: 4px 8px;\n  border-radius: 6px;\n}\n.th-review-edit-modal-row {\n  display: flex; align-items: center; gap: 8px;\n  margin-bottom: 10px; font-size: 12px;\n}\n.th-review-edit-modal-row label { color: var(--tx, #2d1b2e); font-weight: 800; min-width: 56px; }\n.th-review-edit-modal-row .th-review-edit-old {\n  color: var(--tx, #2d1b2e); text-decoration: line-through; opacity: 0.55;\n  font-weight: 700;\n  background-color: rgba(255,228,240,0.4);\n  padding: 3px 8px;\n  border-radius: 6px;\n  word-break: break-all;\n}\n.th-review-edit-modal-row input,\n.th-review-edit-modal-row textarea {\n  flex: 1; padding: 7px 10px;\n  border: 1.5px solid rgba(212,165,116,0.3);\n  border-radius: 8px;\n  background-color: #ffffff !important;\n  background-image: none;\n  color: var(--tx, #2d1b2e);\n  font-size: 13px; font-weight: 700;\n  font-family: inherit;\n  outline: none;\n  transition: border-color 0.18s;\n  -webkit-appearance: none;\n  -moz-appearance: none;\n  appearance: none;\n  color-scheme: light;\n}\n.th-review-edit-modal-row textarea.th-review-edit-input {\n  min-height: 110px;\n  resize: vertical;\n  font-family: var(--font-body, inherit);\n  line-height: 1.5;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n.th-review-edit-modal-row.th-review-edit-modal-row-stack {\n  align-items: flex-start;\n  flex-direction: column;\n  gap: 4px;\n}\n.th-review-edit-modal-row.th-review-edit-modal-row-stack label {\n  margin-bottom: 2px;\n}\n.th-review-edit-modal-row input:focus,\n.th-review-edit-modal-row textarea:focus { border-color: var(--pink); }\n.th-review-edit-modal-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 14px; }\n\n/* 快照项 */\n.th-snapshot-item {\n  display: flex; align-items: center; gap: 10px;\n  padding: 8px 12px;\n  background: rgba(255,255,255,0.6);\n  border: 1px solid rgba(212,165,116,0.18);\n  border-radius: 10px;\n  font-size: 12