er:none; background:transparent; color:inherit; padding:0; display:inline-flex; opacity:.7; transition:opacity .15s; }\n.thw-chip-x:hover { opacity:1; }\n.thw-tag { font-size:10px; font-weight:700; color:var(--thw-muted); background:var(--thw-soft); border-radius:var(--thw-r-xs); padding:2px 6px; }\n\n/* ---- §11.7 空态 / 加载 / 骨架屏 ---- */\n.thw-empty { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px; padding:36px 20px; color:var(--thw-faint); text-align:center; }\n.thw-empty svg, .thw-empty i { width:42px; height:42px; opacity:.45; }\n.thw-empty-t { font-size:13px; font-weight:700; color:var(--thw-muted); }\n.thw-empty-d { font-size:11px; line-height:1.7; max-width:280px; }\n.thw-loading { display:flex; flex-direction:column; align-items:center; gap:12px; padding:34px; color:var(--thw-accent); }\n.thw-loading svg, .thw-loading i { width:34px; height:34px; animation:thw-spin 1.1s linear infinite; }\n.thw-loading-t { font-size:12px; color:var(--thw-muted); }\n@keyframes thw-spin { to { transform:rotate(360deg); } }\n/* 骨架屏：扫光占位（AI 生成时先铺骨架）*/\n.thw-skel { position:relative; overflow:hidden; background:var(--thw-soft); border-radius:var(--thw-r-sm); }\n.thw-skel::after { content:''; position:absolute; inset:0; background:linear-gradient(90deg, transparent, rgba(255,255,255,0.6), transparent); transform:translateX(-100%); animation:thw-shimmer 1.4s var(--thw-std) infinite; }\n@keyframes thw-shimmer { to { transform:translateX(100%); } }\n.thw-skel-line { height:12px; margin:7px 0; }\n.thw-skel-line.s-60 { width:60%; } .thw-skel-line.s-80 { width:80%; } .thw-skel-line.s-40 { width:40%; }\n.thw-skel-av { width:42px; height:42px; border-radius:50%; }\n.thw-skel-card { padding:14px 16px; border-radius:var(--thw-r-lg); background:var(--thw-panel); border:1px solid var(--thw-line-soft); }\n\n/* ---- §11.8 入场动画（卡片错峰升起 / 视图切换 / 列表项）---- */\n@keyframes thw-rise { from { opacity:0; transform:translateY(12px); } to { opacity:1; transform:translateY(0); } }\n@keyframes thw-pop { from { opacity:0; transform:scale(0.96); } to { opacity:1; transform:scale(1); } }\n@keyframes thw-slide-x { from { opacity:0; transform:translateX(22px); } to { opacity:1; transform:translateX(0); } }\n.thw-rise { animation:thw-rise .34s var(--thw-in) both; }\n.thw-rise-stagger > * { animation:thw-rise .38s var(--thw-in) both; }\n.thw-rise-stagger > *:nth-child(1){ animation-delay:.02s } .thw-rise-stagger > *:nth-child(2){ animation-delay:.06s }\n.thw-rise-stagger > *:nth-child(3){ animation-delay:.10s } .thw-rise-stagger > *:nth-child(4){ animation-delay:.14s }\n.thw-rise-stagger > *:nth-child(5){ animation-delay:.18s } .thw-rise-stagger > *:nth-child(6){ animation-delay:.22s }\n.thw-rise-stagger > *:nth-child(7){ animation-delay:.26s } .thw-rise-stagger > *:nth-child(8){ animation-delay:.30s }\n.thw-view-in { animation:thw-slide-x .3s var(--thw-in) both; }\n\n/* ---- §11.9 设置 sheet 区块（各 app 设置面板复用，承载 §6B 全套）---- */\n.thw-set-group { display:flex; flex-direction:column; gap:9px; padding:14px 0; border-bottom:1px solid var(--thw-line-soft); }\n.thw-set-group:last-child { border-bottom:none; }\n.thw-set-glabel { font-size:12px; font-weight:800; color:var(--thw-accent-ink); display:flex; align-items:center; gap:6px; }\n.thw-set-glabel svg, .thw-set-glabel i { color:var(--thw-accent); width:14px; height:14px; }\n.thw-set-hint { font-size:11px; line-height:1.6; color:var(--thw-muted); }\n/* MARK_THW_END */\n\n/* ================================================================\n   §11.W 微博 app 主题（橙红）+ 三栏 master-detail + 卡片/投票/超话/通知/检视\n   ================================================================ */\n.thw-wb-app2 {\n  --thw-accent:#ff6a00; --thw-accent-2:#ff8a3d; --thw-accent-ink:#c2410c;\n  --thw-bg:#fff7f1; --thw-panel:rgba(255,250,245,0.82);\n  --thw-soft:rgba(255,138,61,0.16); --thw-soft-2:rgba(255,106,0,0.14);\n  --thw-line:rgba(120,70,40,0.14); --thw-line-soft:rgba(120,70,40,0.08);\n  --thw-text:#3a2317; --thw-text-2:#6b4a